mapper.select:
SELECT COUNT(*) AS totalInst, SUM(CASE WHEN o.type = 0 THEN 1 ELSE 0 END) AS generalHospitalCount, SUM(CASE WHEN o.type = 1 THEN 1 ELSE 0 END) AS specializedHospitalCount, SUM(CASE WHEN o.type = 2 THEN 1 ELSE 0 END) AS communityHealthCount FROM sys_health_medical_org o LEFT JOIN ( -- 获取每个医疗机构的最新服务记录 SELECT med_org_id, bed_count, treat_volume, bed_utilization_rate, ROW_NUMBER() OVER (PARTITION BY med_org_id ORDER BY stat_time DESC) as rn FROM biz_health_org_svc ) s ON o.id = s.med_org_id AND s.rn = 1
AND o.type = #{instType}
AND s.treat_volume >= #{treatVolumeMin}

SELECT o.id as orgId, o.type AS type, s.bed_count AS bedCount, s.treat_volume AS treatVolume, o.coord_x AS coordX, o.coord_y AS coordY, s.bed_utilization_rate AS bedUsageRate FROM sys_health_medical_org o LEFT JOIN ( -- 获取每个医疗机构的最新服务记录 SELECT med_org_id, bed_count, treat_volume, bed_utilization_rate, ROW_NUMBER() OVER (PARTITION BY med_org_id ORDER BY stat_time DESC) as rn FROM biz_health_org_svc ) s ON o.id = s.med_org_id AND s.rn = 1
AND o.type = #{instType}
AND s.treat_volume >= #{treatVolumeMin}

SELECT o.id as orgId, o.type AS type, s.bed_count AS bedCount, s.treat_volume AS treatVolume, o.coord_x AS coordX, o.coord_y AS coordY, s.bed_utilization_rate AS bedUsageRate FROM sys_health_medical_org o LEFT JOIN ( -- 获取每个医疗机构的最新服务记录 SELECT med_org_id, bed_count, treat_volume, bed_utilization_rate, ROW_NUMBER() OVER (PARTITION BY med_org_id ORDER BY stat_time DESC) as rn FROM biz_health_org_svc ) s ON o.id = s.med_org_id AND s.rn = 1
AND o.type = #{instType}
AND s.treat_volume >= #{treatVolumeMin}
ORDER BY s.treat_volume DESC LIMIT 5
